//
// Embeds every translation from app/assets/i18n into the binary.
// The generated file exposes:
//   pub static LOCALE_FILES: &[(&str, &str)] = &[("en", "...json content..."), ...];
// `_missing_translations_*.json` and `_unused_translations.json` are skipped.

use std::path::PathBuf;

fn main() {
    let manifest_dir = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let i18n_dir = manifest_dir.join("../../app/assets/i18n");
    let out_dir = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR"));

    println!("cargo:rerun-if-changed={}", i18n_dir.display());
    println!("cargo:rerun-if-changed=build.rs");

    let mut locales: Vec<(String, PathBuf)> = Vec::new();
    if let Ok(entries) = std::fs::read_dir(&i18n_dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("json") {
                continue;
            }
            let Some(stem) = path.file_stem().and_then(|s| s.to_str()).map(str::to_string) else {
                continue;
            };
            if stem.starts_with('_') {
                continue;
            }
            println!("cargo:rerun-if-changed={}", path.display());
            let absolute = path.canonicalize().unwrap_or(path);
            locales.push((stem, absolute));
        }
    }

    if locales.is_empty() {
        println!(
            "cargo:warning=no translation files found in {}",
            i18n_dir.display()
        );
    }

    locales.sort_by(|a, b| a.0.cmp(&b.0));

    let mut generated = String::from(
        "// @generated by build.rs - do not edit\n\
         pub static LOCALE_FILES: &[(&str, &str)] = &[\n",
    );
    for (tag, path) in &locales {
        generated.push_str(&format!(
            "    ({tag:?}, include_str!({:?})),\n",
            path.to_string_lossy()
        ));
    }
    generated.push_str("];\n");

    std::fs::write(out_dir.join("locales.rs"), generated).expect("write generated locales.rs");
}
